{
  "id": "recipe-sharing",
  "title": "recipe-sharing",
  "overview": "Exchange portable recipes between households via privacy-scrubbed export bundles (native share or file download fallback) and bundle import intake, schema validation, preview presentation, duplicate detection advisory warning, cancellation, and acceptance into the recipe library as a ready recipe.",
  "requirementCount": 11,
  "requirements": [
    {
      "name": "Offer Share action on eligible ready recipes in loaded detail",
      "text": "The loaded recipe detail sheet SHALL offer a visible Share control (`recipe-share-btn`) when the recipe is ready, possesses a hero image URL that is not a placeholder, and is not in editing mode. The control SHALL NOT be offered when the recipe lacks a ready status, has a placeholder or missing hero image, or is currently being edited.",
      "scenarios": []
    },
    {
      "name": "Generate privacy-scrubbed portable export bundle",
      "text": "Authorized GET `/api/recipes/{id}/share` with household access and member context SHALL return a version 1.0 portable bundle with source `wfs-share`. The bundle SHALL preserve core recipe content, structured instructions, and original images (capped at five). The bundle SHALL scrub personal ratings and notes by setting them to null, and SHALL omit internal entity identifiers and member attribution.",
      "scenarios": []
    },
    {
      "name": "Deliver export bundle via native sharing with download fallback",
      "text": "Activating the Share control SHALL display a persistent loading notice and request the export bundle. If native file sharing is available and permitted, the client SHALL deliver the bundle via native share. If the user cancels native sharing, the action SHALL return cleanly without error feedback or download. If native sharing is unsupported or fails with a non-cancellation error, the client SHALL trigger a file download fallback.",
      "scenarios": []
    },
    {
      "name": "Offer recipe bundle intake on capture entry",
      "text": "The recipe capture view (`/capture`) SHALL offer an \"Import recipe file\" action (`import-recipe-file-btn`) among its intake options. Activating the control SHALL open a file picker accepting plain text files (`.txt,text/plain`) containing a serialized recipe bundle.",
      "scenarios": []
    },
    {
      "name": "Parse and validate imported bundle file payload",
      "text": "Selecting a bundle file SHALL read and parse its JSON content. If the file cannot be parsed as JSON, intake SHALL fail with unreadable file feedback. If the payload is missing required schema fields, contains an invalid source, or has malformed instruction structures or image payloads, intake SHALL fail with invalid bundle feedback.",
      "scenarios": []
    },
    {
      "name": "Present bundle review card and cancellation",
      "text": "Upon successful client parsing, the capture view SHALL display a bundle review card (`bundle-preview-card`). The card SHALL present the recipe name, source attribution, synthesis badge, original image count, structured instructions, hero image, and restored notes and ratings if present in the bundle. The view SHALL offer a Cancel action (`reject-bundle-btn`) that discards the bundle and returns to capture without persistence.",
      "scenarios": []
    },
    {
      "name": "Display advisory warning for existing library duplicates",
      "text": "During bundle preview preparation, the client SHALL query the library for existing recipes matching the bundle's recorded source recipe ID or name. If a match is found, the view SHALL display an advisory warning banner (`duplicate-recipe-warning`) indicating the recipe already exists, with a control to view the existing recipe. The warning SHALL NOT prevent the user from proceeding with import acceptance.",
      "scenarios": []
    },
    {
      "name": "Accept and persist imported recipe bundle into library",
      "text": "Activating \"Import recipe\" (`accept-bundle-btn`) SHALL submit the bundle to POST `/api/recipes/import-bundle`. The API SHALL validate bundle version 1.0, source `wfs-share`, non-empty required content, max 5 original images, and base64 payloads. The API SHALL assign a new identifier upon collision, persist the entity with stored readiness true and importing member attribution, save hero and original images, and return 201 Created.",
      "scenarios": []
    },
    {
      "name": "Present import success screen and navigate home",
      "text": "Upon successful import acceptance, the capture view SHALL transition to a success screen (`bundle-import-success`). The screen SHALL display the imported recipe name and readiness confirmation, and offer a \"Done\" action (`bundle-import-done-btn`). Activating \"Done\" SHALL navigate to Home (`/`). If the import API request fails, the view SHALL display inline error feedback and retain the preview card.",
      "scenarios": []
    },
    {
      "name": "Disable Share while a share operation is pending",
      "text": "After Share activation, the loaded detail sheet SHALL disable its Share control until bundle preparation and delivery settle. Repeated activation of that disabled control SHALL NOT initiate another export request. Once the operation settles, the control SHALL be enabled again if the loaded recipe remains eligible.",
      "scenarios": []
    },
    {
      "name": "Show pending import acceptance on the review action",
      "text": "While a bundle acceptance request is pending and its review remains displayed, the capture view SHALL disable the Import recipe action and show a loading indicator in that action. Repeated activation of the disabled action SHALL NOT submit another import request.",
      "scenarios": []
    }
  ],
  "metadata": {
    "version": "1.0.0",
    "format": "openspec"
  },
  "root": {
    "path": "/Users/alex/Code/whats-for-supper",
    "source": "nearest"
  }
}

